"use client";

import { useMemo } from "react";

import { useDebounce } from "@/hooks";

import { countActiveFilters, filterProducts } from "../lib/product-search";
import { useProductSearchStore } from "../stores/product-search-store";
import type { Product } from "@/types";

/**
 * Shared product search/filter hook.
 *
 * Wraps the shared Zustand store and derives the filtered result list.
 * The query is debounced so typing feels smooth while results update
 * dynamically. Both the product list and the search modal consume this
 * hook — there is exactly one source of state and one filtering path.
 */
export function useProductSearch(products: Product[]) {
  const query = useProductSearchStore((s) => s.query);
  const filters = useProductSearchStore((s) => s.filters);
  const setQuery = useProductSearchStore((s) => s.setQuery);
  const setFilter = useProductSearchStore((s) => s.setFilter);
  const clearFilters = useProductSearchStore((s) => s.clearFilters);
  const reset = useProductSearchStore((s) => s.reset);

  // Debounce only the value used for filtering; the input keeps the
  // raw query so editing stays responsive.
  const debouncedQuery = useDebounce(query, 200);

  const results = useMemo(
    () => filterProducts(products, debouncedQuery, filters),
    [products, debouncedQuery, filters]
  );

  const activeFilterCount = useMemo(() => countActiveFilters(filters), [filters]);

  return {
    /** Raw query (as typed). */
    query,
    setQuery,
    filters,
    setFilter,
    clearFilters,
    reset,
    /** Filtered products. */
    results,
    activeFilterCount,
    isFiltering: query !== debouncedQuery,
  };
}